// AirPods Approvals for Hermes Desktop.
//
// GENERATED by scripts/build.py from src/desktop.js + src/engine.mjs + src/ui.css — edit those.
// Plain ESM loaded uncompiled by the Desktop plugin loader: imports only the SDK and React.
import { Button, Input, ListRow, STATUSBAR_AREAS, PALETTE_AREA, ToggleRow, Codicon, SegmentedControl, atom, host, pluginSettingsHref, useValue } from '@hermes/plugin-sdk'
import { useState } from 'react'
import { jsx, jsxs } from 'react/jsx-runtime'

/*@ENGINE@*/

const PLUGIN_ID = 'airpods-approvals'
const STYLE_ID = 'apa-plugin-style'
const CSS = /*@CSS@*/ ''
const POLL_MS = 2000
const MAX_POLLED_SESSIONS = 12

const $state = atom({ helper: 'off', output: null, motionDenied: false, beats: 0, listening: false, missed: 0, asking: null, last: null, geminiKey: false, test: '' })
const $settings = atom({ ...DEFAULT_SETTINGS })

let plugin = null
let link = null
let coordinator = null

function patch(values) {
  $state.set({ ...$state.get(), ...values })
}

function saveSettings(values) {
  const next = { ...$settings.get(), ...values }
  $settings.set(next)
  plugin.storage.set('settings', next)
}

function randomHex(bytes) {
  return hex(crypto.getRandomValues(new Uint8Array(bytes)))
}

async function sign(secret, text) {
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  return hex(new Uint8Array(await crypto.subtle.sign('HMAC', key, encoder.encode(text))))
}

function pairingToken() {
  return plugin.storage.get('token', '')
}

// Connect makes the token here, starts the helper by opening its app, and offers the token over the
// local socket. The helper takes it only if it has never been paired or Pair Again is open.
async function connectHelper() {
  let token = pairingToken()
  if (!token) {
    token = randomHex(32)
    plugin.storage.set('token', token)
  }
  patch({ helper: 'connecting' })
  link.pairSoon()
  link.connect()
  await plugin.os.openExternal(HELPER_APP)
  plugin.setTimeout(() => {
    if (!link.connected && $state.get().helper === 'connecting') patch({ helper: link.refused ? 'refused' : 'missing' })
  }, 12000)
}

function syncLink() {
  const status = link.status || {}
  const current = $state.get().helper
  patch({
    helper: link.connected ? 'ready' : link.refused ? 'refused' : current === 'connecting' ? 'connecting' : pairingToken() ? 'waiting' : 'off',
    output: status.output || null,
    motionDenied: Boolean(status.motionDenied),
    geminiKey: Boolean(status.geminiKey)
  })
}

function syncCoordinator() {
  const item = coordinator.current
  patch({
    asking: item ? item.kind : null,
    last: coordinator.last,
    ...(item ? {} : { beats: 0, listening: false })
  })
}

function hearProgress(message) {
  const state = $state.get()
  if (message.state === 'listening') patch({ listening: true, beats: 0 })
  else if (message.state === 'beat') patch({ beats: message.beats })
  else if (message.state === 'missed') patch({ beats: 0, missed: state.missed + 1 })
  else if (message.state === 'confirm') patch({ listening: false, beats: 0 })
}

// ── hearing Hermes ──────────────────────────────────────────────────────────────────────────────

function hearEvent(event) {
  if (!event || !event.session_id || !link.connected || !link.status.geminiKey) return
  const payload = event.payload || {}
  if (event.type === 'approval.request') {
    coordinator.offerApproval(event.session_id, { ...payload, request_id: payload.request_id || payload.prompt_id })
  } else if (event.type === 'clarify.request') {
    const questions = Array.isArray(payload.questions)
      ? payload.questions
      : [{ qid: payload.prompt_id, question: payload.question, choices: payload.choices, multi_select: payload.multi_select }]
    coordinator.offerQuestion(event.session_id, payload.prompt_id || payload.request_id, { questions })
  }
}

// Events are the fast path. This poll also catches prompts from sessions Desktop has not opened,
// and notices when a prompt was answered on screen.
let polling = false

async function poll() {
  if (polling || !$settings.get().enabled || !link.connected || !link.status.geminiKey) return
  polling = true
  try {
    const focused = host.state.focusedSessionId.get()
    const reply = await host.request('session.active_list', { current_session_id: focused || null }, 8000)
    const sessions = ((reply && reply.sessions) || []).slice(-MAX_POLLED_SESSIONS)
    await Promise.all(
      sessions.map(async session => {
        const answer = await host.request('approval.pending', { session_id: session.id }, 5000).catch(() => null)
        if (!answer) return
        const pending = answer.approvals || []
        coordinator.reconcile(session.id, pending)
        pending.forEach(request => coordinator.offerApproval(session.id, request))
      })
    )
  } catch {
    // The connection may be down; the next poll tries again.
  } finally {
    polling = false
  }
}

// A practice run: it uses the real helper and gestures, and never touches Hermes.
async function tryGesture() {
  patch({ test: 'Listening', beats: 0 })
  const { listenSeconds, confirmApprovals } = $settings.get()
  const result = await link.ask({
    id: `try-${randomHex(4)}`,
    mode: 'gesture',
    text: 'Nod to say yes, or shake to say no.',
    listenSeconds,
    confirm: confirmApprovals
  })
  const words = { yes: 'You nodded', no: 'You shook your head' }
  const reasons = { ...REASONS, timeout: 'No gesture heard' }
  patch({ test: words[result.answer] || reasons[result.reason] || 'Stopped', beats: 0, listening: false })
}

// ── interface ───────────────────────────────────────────────────────────────────────────────────

function Beats({ large }) {
  const { beats, missed } = useValue($state)
  return jsx('span', {
    className: `apa-beats${large ? ' apa-beats--large' : ''}${missed % 2 ? ' apa-beats--miss' : ''}`,
    'aria-label': `${beats} of 3 beats`,
    children: [1, 2, 3].map(n => jsx('span', { className: n <= beats ? 'apa-beat apa-beat--on' : 'apa-beat' }, n))
  })
}

function StatusChip() {
  const state = useValue($state)
  const settings = useValue($settings)
  if (!settings.enabled) return null
  const title = state.helper === 'ready' ? (state.output ? `AirPods Approvals: ${state.output}` : 'AirPods Approvals: connect your AirPods') : 'AirPods Approvals: helper not connected'
  return jsx('button', {
    className: 'apa-chip',
    onClick: () => host.navigate(pluginSettingsHref(PLUGIN_ID)),
    title,
    type: 'button',
    children: state.listening
      ? jsx(Beats, {})
      : [jsx(Codicon, { name: state.helper === 'ready' && state.output ? 'unmute' : 'mute', size: '0.8rem' }, 'i')]
  })
}

function helperText(state) {
  if (state.helper === 'missing') return 'Helper not found'
  if (state.helper === 'refused') return 'Choose Pair Again in the menu bar, then Connect'
  if (state.helper === 'connecting') return 'Connecting'
  if (state.helper === 'waiting') return 'Helper not running'
  if (state.helper === 'off') return 'Not connected'
  if (state.motionDenied) return 'Motion access is off'
  return state.output ? `Ready on ${state.output}` : 'Connect your AirPods'
}

const REASONS = {
  unavailable: 'AirPods not ready',
  noMotion: 'No head movement. Are both AirPods in?',
  noKey: 'Add a Gemini key',
  noVoice: "Gemini didn't answer",
  lost: 'AirPods lost'
}

function outcomeText(last) {
  if (!last) return 'Nothing asked yet'
  const text = { approved: 'Approved', denied: 'Denied', answered: `Answered: ${last.detail}`, read: 'Read aloud', stale: 'Already answered on screen', error: 'Could not send that answer' }
  if (last.outcome === 'unanswered') return `${REASONS[last.detail] || 'No answer given'}, left on screen`
  return text[last.outcome] || last.outcome
}

// The key goes straight to the helper, which keeps it in the Keychain. Desktop never stores it.
function KeyRow({ state }) {
  const [draft, setDraft] = useState('')
  const linked = state.helper === 'ready'
  if (state.geminiKey) {
    return jsx(ListRow, {
      title: 'Gemini key',
      description: 'Saved',
      action: jsx(Button, { onClick: () => link.send({ type: 'setKey', key: '' }), size: 'sm', type: 'button', variant: 'outline', children: 'Remove' })
    })
  }
  const save = () => {
    if (!draft.trim()) return
    link.send({ type: 'setKey', key: draft.trim() })
    setDraft('')
  }
  return jsx(ListRow, {
    title: 'Gemini key',
    action: jsxs('span', {
      className: 'apa-key',
      children: [
        jsx(Input, {
          'aria-label': 'Gemini API key',
          autoComplete: 'off',
          disabled: !linked,
          onChange: event => setDraft(event.target.value),
          onKeyDown: event => event.key === 'Enter' && save(),
          placeholder: 'Paste key',
          spellCheck: false,
          type: 'password',
          value: draft
        }),
        jsx(Button, { disabled: !linked || !draft.trim(), onClick: save, size: 'sm', type: 'button', variant: 'default', children: 'Save' })
      ]
    })
  })
}

function SettingsPage() {
  const state = useValue($state)
  const settings = useValue($settings)
  const ready = state.helper === 'ready' && Boolean(state.output) && !state.motionDenied && state.geminiKey
  return jsxs('div', {
    children: [
      jsx(ListRow, {
        title: 'Helper',
        description: helperText(state),
        action: state.helper === 'ready' ? null : jsx(Button, { onClick: () => void connectHelper(), size: 'sm', type: 'button', variant: 'default', children: 'Connect' })
      }),
      jsx(KeyRow, { state }),
      jsx(ListRow, {
        title: 'Try it',
        description: state.test || 'Three quick beats',
        action: jsxs('span', {
          className: 'apa-try',
          children: [jsx(Beats, { large: true }), jsx(Button, { disabled: !ready || Boolean(state.asking), onClick: () => void tryGesture(), size: 'sm', type: 'button', variant: 'outline', children: 'Start' })]
        })
      }),
      jsx(ListRow, { title: 'Last request', description: outcomeText(state.last) }),
      jsx(ToggleRow, { checked: settings.enabled, label: 'Answer with my head', onChange: on => saveSettings({ enabled: on }) }),
      jsx(ToggleRow, { checked: settings.confirmApprovals, label: 'Nod twice to approve', description: 'A second round before anything runs.', onChange: on => saveSettings({ confirmApprovals: on }) }),
      jsx(ToggleRow, { checked: settings.questions, label: 'Read questions aloud', onChange: on => saveSettings({ questions: on }) }),
      jsx(ListRow, {
        title: 'Time to answer',
        action: jsx(SegmentedControl, {
          onChange: value => saveSettings({ listenSeconds: Number(value) }),
          options: [{ id: '5', label: '5s' }, { id: '8', label: '8s' }, { id: '12', label: '12s' }],
          value: String(settings.listenSeconds)
        })
      })
    ]
  })
}

// ── registration ────────────────────────────────────────────────────────────────────────────────

export default {
  id: PLUGIN_ID,
  name: 'AirPods Approvals',
  description: 'Hear approvals in your AirPods and answer with a nod or a shake.',
  register(ctx) {
    plugin = ctx
    if (!document.getElementById(STYLE_ID)) {
      const style = document.createElement('style')
      style.id = STYLE_ID
      style.textContent = CSS
      document.head.appendChild(style)
      ctx.onDispose(() => style.remove())
    }

    $settings.set({ ...DEFAULT_SETTINGS, ...ctx.storage.get('settings', {}) })

    link = new HelperLink({
      createSocket: url => new WebSocket(url),
      token: pairingToken,
      sign,
      nonce: () => randomHex(16),
      onChange: syncLink,
      setTimer: (fn, ms) => ctx.setTimeout(fn, ms)
    })
    link.progress = hearProgress

    coordinator = new Coordinator({
      rpc: (method, params, timeout) => host.request(method, params, timeout),
      link,
      settings: () => $settings.get(),
      newId: () => randomHex(8),
      onChange: syncCoordinator
    })

    ctx.onEvent('*', hearEvent)
    ctx.setInterval(() => void poll(), POLL_MS)
    ctx.onDispose(() => link.close())

    ctx.registerMany([
      { id: 'status', area: STATUSBAR_AREAS.right, order: 112, render: () => jsx(StatusChip, {}) },
      { id: 'cmd-try', area: PALETTE_AREA, data: { id: 'airpods-approvals.settings', label: 'AirPods Approvals: Open settings', keywords: ['airpods', 'nod', 'approve'], run: () => host.navigate(pluginSettingsHref(PLUGIN_ID)) } }
    ])
    ctx.registerSettingsPage?.({ id: 'settings', title: 'AirPods Approvals', icon: 'unmute', render: () => jsx(SettingsPage, {}) })

    // Once paired, Desktop starts the helper itself. Only the first launch needs Connect.
    if (pairingToken()) {
      link.connect()
      ctx.setTimeout(() => {
        if (!link.connected) void ctx.os.openExternal(HELPER_APP)
      }, 1500)
    }
  }
}
